import{p as m}from"./page-banner-CBMLmk-e.js";import{_,r as s,b as e,f,d as t,t as l,F as I,e as g,j as i,k as y}from"./index-C0LRyjh0.js";const k={class:"container"},B={class:"content"},F={class:"introduction"},H={class:"introduction"},V={class:"development_history"},b={class:"timeline-container"},x={class:"timeline-content"},T={__name:"AboutView",setup(w){const a=s("关于我们"),r=s([{year:"2024年11月",content:"香港理工大学与合肥市庐阳区签署合作协议",position:"left"},{year:"2025年8月",content:"研究院正式落地合肥庐阳大数据产业园",position:"right"}]),d=s("香港理工大学(港理大)创立于1937年，是一所科研实力强劲的综合性研究型大学，于《2025年QS世界大学排行榜》中位列全球第57位。港理大秉承校训「开物成务　励学利民」的精神，矢志成为一所创新型世界级大学，并以肩负社会重任为宗旨。"),u=s("港理大为学生提供优质的全面教育，致力培育具良好国民意识、全球视野与社会责任感的「明日领袖」；同时推动具影响力的创新与跨学科研究，以应对全球最迫切的挑战。知识转移与创业文化亦是港理大的基石，大学着重研以致用——将所研发的科技转化为实际应用。港理大追求卓越，努力不懈，深得国际认可，持续位居全球百强学府之列。港理大将继续以其雄厚根基，与各界策略伙伴合作，力求造福香港、国家乃至全球。"),c=s("为进一步推动空天信息与生物医疗精密传感器等领域创新发展，促进科技成果产业化，推进合肥市科技创新与产业升级，香港理工大学（理大）与合肥市庐阳区人民政府达成协议，共同创建「香港理工大学合肥技术创新研究院」（研究院），旨在开展深度有效的产学研合作及培育优秀人才。研究院将开展多个项目，重点聚焦生物医学传感精密技术和航天资讯，促进相关领域的科研发展、学术交流、人才培养和知识转移。理大将发挥其科研实力和学术优势，透过是次合作在合肥建设顶尖的科技创新平台。"),p=s("签约仪式于 10 月 25 日在合肥市举行。理大副校长（研究及创新）赵汝恒教授及合肥市庐阳区区政府副区长时坤先生代表双方签署协议，并由理大协理副校长（内地研究拓展）董澄教授、理大土地测量及地理资讯学系主任陈武教授、理大国家轨道交通电气化与自动化工程技术研究中心（香港分中心）主任倪一清教授，以及合肥市庐阳区区委书记高强先生、合肥市庐阳区区委办主任朱华军先生、合肥市庐阳区庐阳经济开发区管委会主任沉兵先生见证。");return s("为进一步推动空天信息与生物医疗精密传感器等领域创新发展，促进科技成果产业化，推进合肥市科技创新与产业升级，香港理工大学与合肥市政府，庐阳区政府合作共建港理大（合肥）技术创新研究院有限公司。"),s("将聚焦空天信息与生物医疗精密传感器两大领域，开展技术研发、平台建设及成果转化，致力于打造国际一流的产学研合作转化基地。"),(A,n)=>(i(),e("div",k,[f(m,{mainTitle:a.value},null,8,["mainTitle"]),t("div",B,[t("div",F,[n[0]||(n[0]=t("div",{class:"title"},[t("span",{class:"name"},"香港理工大学简介")],-1)),t("p",null,l(d.value),1),t("p",null,l(u.value),1),n[1]||(n[1]=t("div",{class:"college_pic"},null,-1))]),t("div",H,[n[2]||(n[2]=t("div",{class:"title"},[t("span",{class:"name"},"港理工(合肥)技术创新研究院简介")],-1)),t("p",null,l(c.value),1),t("p",null,l(p.value),1),n[3]||(n[3]=t("div",{class:"sign_pic"},null,-1))]),t("div",V,[n[5]||(n[5]=t("h2",null,"研究院建设历程",-1)),n[6]||(n[6]=t("span",null,null,-1)),t("div",b,[(i(!0),e(I,null,g(r.value,(o,v)=>(i(),e("div",{key:v,class:y(["timeline-item",o.position])},[n[4]||(n[4]=t("div",{class:"timeline-node"},null,-1)),t("div",x,[t("h3",null,l(o.year),1),t("p",null,l(o.content),1)])],2))),128))])])])]))}},N=_(T,[["__scopeId","data-v-e3030213"]]);export{N as default};
